import json
lines=[json.loads(l) for l in open('journal/be879027-0148-45e9-baaa-63ee1e03115f.jsonl')]
msgs=[]
for d in lines:
    m=d.get('message')
    if not m or d.get('type') not in('user','assistant'): continue
    c=m.get('content')
